import{_ as t,o as e,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"Custom Plates CSV","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/custom_platecsv/index.md","filePath":"guide/reports/custom_platecsv/index.md","lastUpdated":1790346505000}'),r={name:"guide/reports/custom_platecsv/index.md"},s=o('<h1 id="custom-plates-csv" tabindex="-1">Custom Plates CSV <a class="header-anchor" href="#custom-plates-csv" aria-label="Permalink to &quot;Custom Plates CSV&quot;">​</a></h1><p>The Custom Plates CSV exports plate part data as CSV files, which can be opened in spreadsheet applications or imported into other systems.</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> ZIP containing one CSV file (or XLS file) per group</li><li><strong>Content:</strong> Plate parts with the columns you select: Material, Plate Size W*L, Width, Length, Height, Part Count, Part Reference, Project, Panel Name, Finish and Comments. All are on by default.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Export CSV file as XLS file</strong></td><td>Write each file as XLS instead of CSV.</td></tr><tr><td><strong>Add column names in the first row</strong></td><td>Add a header row.</td></tr><tr><td><strong>Separator</strong></td><td><code>;</code> (default) or <code>,</code>.</td></tr><tr><td><strong>Group parts from the report in the same folder</strong></td><td><em>By Phase</em>, <em>By Batch</em> (default), <em>By Panel</em> or <em>By Selected Panels</em>: one file per phase, batch or panel, or one file for everything.</td></tr><tr><td><strong>Selectable Columns</strong></td><td>The columns to include.</td></tr></tbody></table><p>With <strong>Select by Part Batches</strong> on, you pick part batches instead of panels and get one file per part batch.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Use this report when you need raw plate data in a format that can be imported into external tools — for example, ERP systems, cutting optimization software, or custom spreadsheets.</p>',9),n=[s];function i(d,l,c,h,p,u){return e(),a("div",null,n)}const _=t(r,[["render",i]]);export{f as __pageData,_ as default};
